INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N035-03','CN0280','S035-03','历史产能、膜及支路冲突','3.1.3–4、3.3.1 p47、表3.3-1','原20000m³/a预处理、17000m³/a再生，表3.1-4又列设计17000t/a及2018实产1032t/a，不转换；2020既有前处理120m³/d、再生150m³/d；微电解絮凝还原沉淀、水解AO多介质RO。3.3.1前段50%回用与表3.1-3全链后回用的表述不同，RO产浓水去向不明；污泥委托宁波科环，历史非当前。','WEB_PRIMARY','公开正文或摘录；非原件归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N035-04','CN0280','S035-03','扩建设计盐与水量','4.3.1、4.5.3','新增分股产生1436.5t/d及排放283.2t/d，设计总回用80.5%，提钛提钨水由50%提高80%，报告称受盐度≤500mg/L、电导≤100μS/cm约束，二者为报告要求非实测；离子交换约3%NaCl、解析约5%。表4.3-2全厂107124t/a，正文107919t/a不一致；生产105909、生活1215t/a，保留表值并记差异。','WEB_PRIMARY','公开正文或摘录；非原件归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N035-05','CN0280','S035-03','验收样本','表3.4-1/2，p51–52','2016年5月19/20各4次采样，2020报告引用2016-08一期先行验收，报告称监测负荷100%，非年度产量；136条单样本，低于检出限保留，日均半检出值不当实测；截图404，文本表可读。','WEB_PRIMARY','公开正文或摘录；非原件归档','2026-11-28');
